css:
.loader {
  position: relative;
  width: 48px;
  height: 56px;
}
.loader::before {
  content: "";
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 6px;
  height: 40px;
  margin-left: -3px;
  background: #6366f1;
  clip-path: polygon(30% 0, 70% 0, 100% 100%, 0 100%);
}
.loader i {
  position: absolute;
  top: -3px;
  left: 50%;
  width: 38px;
  height: 38px;
  margin-left: -19px;
  border-radius: 50%;
  background: conic-gradient(from 0deg, #6366f1 0 12deg, transparent 12deg 120deg, #6366f1 120deg 132deg, transparent 132deg 240deg, #6366f1 240deg 252deg, transparent 252deg 360deg);
  animation: spin 0.9s linear infinite;
}
.loader i::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 9px;
  height: 9px;
  margin: -4.5px 0 0 -4.5px;
  border-radius: 50%;
  background: #4338ca;
}
@keyframes spin { to { transform: rotate(360deg); } }
